def extended_floyd_warshall(edges):
    num_v = len(edges)
    dist = [[float('inf')] * num_v for _ in range(num_v)]

    for u, v, w in edges:
        dist[u-1][v-1] = w
        dist[v-1][u-1] = w

    for k in range(num_v):
        for u in range(num_v):
            for v in range(num_v):
                dist[u][v] = min(dist[u][v], dist[u][k] + dist[k][v])

    for u in range(num_v):
        for v in range(num_v):
            dist[u][v] = min(dist[u][v], 0 if u == v else float('inf'))

    return dist

