from collections import defaultdict
from typing import List

def calculate_smallest_sequence(nodes: List[int], edges: List[List[int]]) -> List[int]:
    num_nodes = len(nodes)
    graph = defaultdict(lambda: defaultdict(set))

    for u, v, _ in edges:
        graph[u][v].add(v)

    def get_predecessors(node: int, visited: set[int]) -> int:
        if node + 1 not in visited:
            predecessors[node] = node + 1
            for neighbor in graph[node]:
                if neighbor + 1 in predecessors:
                    predecessors[node] = min(predecessors[node], get_predecessors(neighbor + 1, visited))
        return predecessors[node]

    predecessors = [None] * num_nodes
    if 0 in predecessors:
        raise ValueError("Unable to construct the sequence")
    get_predecessors(0, {0})

    result = [nodes[0] for _ in range(num_nodes)]
    pred = predecessors[0]
    for i in range(1, num_nodes):
        if not pred:
            return "-1"
        result[i], pred = pred, i

    return result

