        dy[start] += [1, 0], [-1, 0]
        for d in dx[start]:
            mx[start][d] = -1
        for d in dy[start]:
            my[start][d] = -1

    for l in range(N):
        for u in A:
            if mx[u][0] == -1 or mx[u][1] == -1:  # own transition
                nx, ny = mx[u], my[u]
                for i, d in enumerate(dx[u]):
                    cx, cy = u, u + d
                    if cx not in A:  # out of bound
                        nx[i] = cy
                    else:
                        if mx[cx][d] != -1:
