def build_max_suffix(graph_end_points, current_sequence, current_index, suffix_start):
    max_suffix = ""
    for index, node in enumerate(current_sequence):
        if node < suffix_start + 2 and index < current_index and graph_end_points[node] >= suffix_start:
            max_suffix = node + current_sequence[:index] + current_sequence[index:]
            return build_max_suffix(graph_end_points, max_suffix, current_index, suffix_start)
    return max_suffix

def solve(n, m, edges):
    end_points = {node: [-1] for node in range(n+1)}
    for u, v, label in edges:
        end_points[u].append(float('inf'))
        end_points[v].append(float('inf'))
    labels = {}
