        if start not in labels:
            if labels_for_start != label:
                return -1
            labels[start] = sum(ord(char) - ord('a') + 1 for char in labels_for_start)
        else:
            if labels[end_points[start][-1]] != sum(ord(char) - ord('a') + 1 for char in labels[start]):
                return -1
    sequence = []
    for node in labels:
        if labels.get(node, None) is not None:
            prefix_max = max(labels[node])
            sequence.extend(
                [prefix_max + ord(char) - ord('a')
                 for char in "".join(labels[node])]
            )
    if len(sequence) == 0:
        return -1
    sequence.sort()
    return sequence

def traverse(end_points, start_point):
    seen, stack, visited, flatten = set(), [start_point], set(), list()
    while stack:
        current = stack.pop()
        flatten.append(current)
        if current in end_points and end_points[current][-1] == 0:
            continue
        if current in seen:
            continue
        seen |= {current}
        for next in end_points[current]:
            if next not in visited:
                visited.add(next)
                stack.append(next)
                break
    return zip(flatten[::-1], flatten[::-1][1:])

def main():
