import sys
from typing import List

class Segment:
    def __init__(self, l, r):
        self.left = l
        self.right = r

class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y
        self.shade_time = 0

def get_intersection(l1, r1, l2, r2):
    if l1 <= l2 <= r2 or r1 <= l2 <= r2:
        return l2, r2
    elif l1 <= l1 <= r2 or l2 <= l1 <= r2:
        return l1, r1
    else:
        return None

def get_segment_intersection(segment1, segment2, point):
    l, r = get_intersection(segment1.left, segment1.right, point.x, segment2.left)
    if l is None:
        l, r = get_intersection(segment1.left, segment1.right, segment2.right, point.x)
    if r is None:
        return
    t = (point.x - l) / (r - l)
    if t >= point.y:
        return
    l = point.x - t * (point.x - segment1.left)
    r = min(point.y * (r - l) + l, point.y * (r2 - l2) + l2)
    closest_left, closest_right = get_intersection(segment1.left, segment1.right, l, r)
    if closest_left <= segment2.left or closest_right >= segment2.right:
        return
    segment1.left = closest_left
    segment1.right = closest_right
    max_t = min(point.y, min(t, t + (r - closest_right) / (point.y - segment1.left)))
    segment1.shade_time = max(0, segment1.shade_time + max_t * segment1.right - max_t * segment1.left)
    segment1.shade_time = max(0, segment1.shade_time + (r2 - closest_right) + (min(point.x, r2) - segment2.right) + max(point.x, r))

