        while True:
            intersection = get_intersection(l, r, segment.left, segment.right)
            if not intersection:
                break
            if x < intersection[0] or x > intersection[1]:
                break
            if y < segment.left or y > segment.right:
                break
            res = segment.shade_time
            if l < segment.left < x < r < segment.right < intersection[0]: 
