        if current_bracket == 0:
            overall_ink += 2
            if stack:
                stack.pop()
                if stack:
                    stack.pop()
        elif current_bracket == 1:
            overall_ink += 4
            if stack:
                stack.pop()
                if stack:
                    stack.pop()
