def find_center_caves(n, transitions):
    graph = defaultdict(list)
    in_degree = [0] * (n + 1)

    for a, b in transitions:
        graph[a].append(b)
        in_degree[b] += 1

    center_caves = []
    visited = set()
    stack = [i for i in range(1, n + 1) if in_degree[i] == 1]

    while stack:
        node = stack.pop()
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 1:
                    stack.append(neighbor)
            graph[neighbor].remove(node)

    for i in range(1, n + 1):
        if graph[i] and not in_degree[i]:
            center_caves.append(i)

