from heapq import heappush, heappop

def find_shortest_routes(n, m, roads):
    # Build graph and shortest_path matrix
    graph = {i: {} for i in range(n)}
    shortest_path = [[1e9] * n for _ in range(n)]

    for i in range(m):
        u, v = roads[i][0], roads[i][1]
        graph[u][v] = graph[v][u] = 1
        shortest_path[u][v] = 1
        shortest_path[v][u] = 1

    # Dijkstra's shortest path algorithm
    for k in range(n):
        for u in range(n):
            for v in graph[u]:
                if shortest_path[u][k] + graph[u][v] < shortest_path[k][v]:
                    shortest_path[k][v] = shortest_path[u][k] + graph[u][v]
                    graph[k][v] = graph[u][v]

    # Find the shortest paths shorter than n
    for path in shortest_path:
        if path[-1] < n:
            return len(path) - 1, path[:-1]

    return -1

