def find_stable_grids(students, threshold):
    counts = [0] * (len(students) + 1)
    grid_count = {}
    for d_amount in sorted(students):
        if not grid_count:
            for size in range(d_amount, 0, -1):
                counts[size] += 1
            grid_count[d_amount] = n_choose_k(d_amount, d_amount)
        else:
            if size not in grid_count:
                for size2 in range(1 + size, d_amount + 1):
                    counts[size2] += counts[size2 - size]
                grid_count[d_amount - size] = n_choose_k(d_amount - size, d_amount - size)
            for size in range(size - 1, 0, -1):
                if size not in grid_count:
                    for size2 in range(size, 0, -1):
                        counts[size2] += counts[size2 + size]
                    grid_count[d_amount + size] = n_choose_k(d_amount + size, d_amount + size)
        if size in grid_count:
            grid_count[d_amount] += grid_count[size]
    total_ways = 0
    total_group_sum = 0
    for size in range(len(students) + 1):
        if total_group_sum + size <= threshold and total_group_sum - size >= 0 and size in grid_count:
            total_ways += grid_count[size] * counts[size]
            total_ways %= (10**9 + 7)
            total_group_sum += size
        elif size in grid_count:
            total_group_sum += size
            total_ways += grid_count[size]
