def topological_sort(nodes, edges):
    in_degree = {node: 0 for node in nodes}
    for u, v in edges:
        in_degree[v] += 1

    queue = [node for node in nodes if in_degree[node] == 0]

    for _ in range(len(nodes)):
        current = queue.pop(0)
        for from_node, _, to_node in edges[current]:
            in_degree[from_node] -= 1
            if not in_degree[from_node]:
                queue.append(from_node)

    sorted_nodes = [node for node in queue]
    return sorted_nodes

def find_sequence(nodes, edges):
    sorted_nodes = topological_sort(nodes, edges)

    output = [-1 if i < 1 else sorted_nodes[i] for i in range(len(sorted_nodes)-1)]
    return output

