            next_hops[lexicographical_head]['weight'] = next_let
        elif next_hops[lexicographical_head]['min_weight'] == next_count and next_hops[lexicographical_head]['weight'] > next_let:
            next_hops[lexicographical_head]['weight'] = next_let

