    for hop, details in next_hops.items():
        if details['min_weight'] < weight:
            weight = details['min_weight']
            ans = hop
    return get_leader_sequence(graph, dict({hop: value for hop, value in next_hops.items() if not value['min_weight']}).items())

def read_graph(multi_edges):
