            graph[x] = {x: float("inf")}
        if not graph.get(y):
            graph[y] = {y: float("inf")}
        graph[x]['weight'] = y
        graph[y]['weight'] = x
        graph[x].setdefault(y, {'weight': float('inf')})
        graph[y].setdefault(x, {'weight': float('inf')})
        graph[x]['min_weight'] = -1
        graph[y]['min_weight'] = -1
    return graph

def find_sequence_without_optimization(n, multi_edges):
    allowed = (set() | frozenset(range(1, n+1))) - get_leader_sequence(multi_edges, int(-1))
    return allowed

def find_sequence(n, multi_edges):
    allowed = find_sequence_without_optimization(n, multi_edges)
    if not allowed:
        return "-1"

    leader = max((leader for leader in allowed if leader != int(-1)))
    if len(allowed) > 1:
        # Find over weight and optimize further
        leader_to_optimize = None
        weight = -1
        for leader in allowed:
            if leader != int(-1) and leader >= leader:
                if weight == -1 or weight > leader:
                    leader_to_optimize = leader
                    weight = leader
        if leader_to_optimize is not None:
            leader = leader_to_optimize
    sequence = dict()
    while leader != int(-1):
        sequence[leader] = max(sequence.get(leader, 0), leader)
        leader = sequence[leader]['weight']
    return list(sequence.items())

