def generate_stacks(ais, k):
    n = len(ais)
    groups = [[] for _ in range(n)]
    stack = []
    current = 0
    finished = []

    while current < n or stack:
        if stack:
            while stack and stack[-1] < current:
                found = False
                for i in range(n):
                    if i not in finished and stack[-1] <= i:
                        current = i
                        stack.append(i)
                        found = True
                        break
                if not found:
                    raise ValueError("No stack element found that can include the current value.")
        else:
            for i in range(n):
                if i not in finished:
                    current = i
                    stack.append(i)
                    if i - current != k:
                        groups[current].append(group)
                        finished.append(current)
                        break

    return groups

def solve(ais, k):
    n = len(ais)
    group_counts = [1 for _ in range(n)]
    stack = []
    group_stack = defaultdict(int)
    for i in range(n):
        current = i
        while stack and stack[-1] < current:
            found = False
            for j in range(n):
                if not found and (i - j == k or j - i == k):
                    found = True
                    group_stack[(i - j) % n] += 1
                    group_stack[(j - i) % n] += 1
                    continue
                if j not in finished and stack[-1] <= j:
                    group_stack[(i - j) % n] += 1
                    group_stack[(j - i) % n] += 1
                    current = j
                    stack.append(j)
                    finished.append(j)
                    break
        if not found:
            raise ValueError("No finishing element found that can include the current value.")

    total_ways = 1
    for group in group_counts:
        ways = 1
        for counted_group in group_stack:
            if group_stack[counted_group] == group:
                ways *= group_stack.pop(counted_group)
        total_ways *= ways
        total_ways %= (10**9 + 7)

    return total_ways

