from typing import List

class SynchronizationSystem:
    def countGoodSets(self, n: int, m: int, T: List[str]) -> int:
        MOD = 10**9 + 7

        # Count the number of ways to choose S if we delete one element
        initial_cases = self.getPossibleSets(n, m)

        # For each element in T, calculate the possible sets and add them to the previous cases
        for num in T:
            xor_to_delete = int(num, 2)
            current_cases = len(self.getSynchronizedSets(n, 0, xor_to_delete))
            initial_cases = (initial_cases * current_cases) % MOD

        return initial_cases

    def getPossibleSets(self, n: int, m: int) -> List[List[str]]:
        masks = [2**i - 1 for i in range(m)]
        possible_sets = []
        for bit in range(1 << m):
            if bin(bit).count('1') == 1:
                possible_sets.append(['0' * bit] + ['1' for _ in range(m - bit)])
        return possible_sets

    def getSynchronizedSets(self, n: int, carry: int, xor_to_delete: int) -> List[List[str]]:
        if n == m:
            return [['1' if i == carry or j == xor_to_delete else '0' for i in range(m)] for j in range(m)]

        sets = []
        for idx in range(n + 1):
            if idx <= carry:
                sets.extend(self.getSynchronizedSets(n + 1, idx, xor_to_delete))
            if (n - idx) <= (m - carry):
                sets.extend(self.getSynchronizedSets(n + 1, n - idx, xor_to_delete))

        return sets
